update pb_ai.kb_chunks set chunk = $kb${"id": "osha-loi-trench-stacking-1", "state": "US", "tier": "core", "title": "Stacked trench boxes: does the top box in a stack need the full-depth rating? (OSHA: no)", "topic": "OSHA interpretation letters on trenches and manholes", "text": "Short answer: no. OSHA does not require every box in a stack to be rated for the whole trench depth; each box must be used no deeper than the depth it is designed for. OSHA letter of October 29, 1991 (stacking trench boxes): stacked shields \"do not all have to be designed to resist the forces calculated for the deepest part of the trench.\" \"The standard only requires that the shields be used at a depth not greater than that for which they are designed.\" So the bottom box must be rated for the full trench depth in the soil type the competent person classified, and a box higher in the stack only for the depth where it sits; put the deeper-rated box at the bottom. OSHA suggested a marking system that shows the maximum depth of each shield so a lighter box does not end up on the bottom. Stack only as the manufacturer's tabulated data allows (its box combinations, stacking pins or connectors and depth limits), keep that data at the jobsite, and get the manufacturer's written approval for anything outside it (29 CFR 1926.652(c)(2)). Do not mix this up with 1926.652(g)(2), which is not a stacking rule: digging up to 2 ft below the bottom of a shield is allowed only if the shield is designed for the full trench depth and there is no sign of soil loss from behind or below it. Where a box sits in the vertical lower part of a sloped trench, it must extend at least 18 inches above the top of the vertical side (Appendix B). No one may be in a shield while it is installed, removed or moved vertically (1926.652(g)(1)(iv)).", "source": "OSHA Standard Interpretation, 1991-10-29 (1926.650, 1926.652); 29 CFR 1926.652(c)(2), (g)(1)(iv), (g)(2); Appendix B to Subpart P", "url": "https://www.osha.gov/laws-regs/standardinterpretations/1991-10-29", "checked": "2026-11-20", "edition": "OSHA letter of interpretation and eCFR 1926.652 (current), read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2971 and chunk->>'id' = 'osha-loi-trench-stacking-1';
